"""Apply the approved collection-centre presentation to the R6 build."""
import re
from pathlib import Path


def apply(text):
    page = '''function r6Page(){const tabs=[['sources','远程日志源',R6.sources.length],['storage','存储位置',R6.roots.length],['cache','解析缓存',LB.state.cache?.items?.length??0],['events','运行记录',R6.events.length]];return `<section class="r6-content collection-center"><header class="collection-head"><div class="r6-tabs" role="tablist" aria-label="采集中心视图">${tabs.map(([id,name,count])=>`<button id="collection-tab-${id}" class="r6-tab ${R6.tab===id?'active':''}" role="tab" tabindex="${R6.tab===id?0:-1}" aria-controls="collection-panel" aria-selected="${R6.tab===id}" data-r6="tab" data-id="${id}">${name}<small>${count}</small></button>`).join('')}</div><div class="collection-actions">${r6Btn('资源设置','tuning','sliders','ghost')}${R6.tab==='sources'?r6Btn('添加日志源','new-source','plus','primary'):R6.tab==='storage'?r6Btn('添加存储位置','new-root','plus','primary'):''}</div></header><div id="collection-panel" class="collection-panel" role="tabpanel" aria-labelledby="collection-tab-${R6.tab}">${R6.tab==='sources'?r6Sources():R6.tab==='storage'?r6Storage():R6.tab==='cache'?r6Cache():r6Events()}</div></section>`;}'''
    sources = '''function r6Sources(){const rows=r6SourceRows();return `<div class="r6-toolbar"><div class="search-box">${I('search')}<input id="r6-source-search" value="${E(R6.search)}" placeholder="搜索名称、主机、目录…" aria-label="搜索远程日志源"></div><select class="select" id="r6-source-filter" aria-label="日志源状态">${[['all','全部状态'],...Object.entries(r6States).map(([id,v])=>[id,v[0]])].map(([id,t])=>`<option value="${id}" ${R6.sourceFilter===id?'selected':''}>${t}</option>`).join('')}</select><span class="spacer"></span><span class="collection-count">${rows.length} 项</span>${r6Btn('','refresh','refresh','icon ghost','aria-label="刷新日志源状态"')}</div><div class="r6-pane"><div class="r6-table-scroll" data-scroll="r6-sources">${rows.length?`<table class="r6-table collection-sources"><colgroup><col style="width:26%"><col style="width:25%"><col style="width:16%"><col style="width:11%"><col style="width:11%"><col style="width:11%"></colgroup><thead><tr><th>日志源</th><th>目录 / 存储位置</th><th>同步状态</th><th class="collection-number">归档量</th><th class="collection-number">索引覆盖</th><th>操作</th></tr></thead><tbody>${rows.map(x=>`<tr class="${R6.selected===x.id?'selected':''}"><td><div class="r6-source-title"><span class="collection-symbol">${I('server')}</span><div class="grow"><button class="r6-link" data-r6="source-detail" data-id="${E(x.id)}">${E(x.name)}</button><div class="r6-meta">${E(r6Protocols[x.protocol])} <span class="mono">${E(x.endpoint)}</span></div></div></div></td><td><div class="r6-path">${E(x.maps[0]?.remote||'未配置')}</div><div class="r6-meta">${E(r6Root(x.maps[0]?.root)?.name||'未配置')}${x.maps.length>1?'　+'+(x.maps.length-1)+' 个目录':''}</div></td><td>${r6Status(x)}<div class="r6-meta">${E(x.lag)}</div></td><td class="collection-number"><span class="mono">${E(x.raw)}</span><div class="r6-meta">${E(x.count)} 个文件</div></td><td class="collection-number">${x.count?`<span class="mono">${E(x.coverage)}%</span><div class="r6-progress" aria-label="索引覆盖 ${E(x.coverage)}%"><span style="width:${Math.max(0,Math.min(100,Number(x.coverage)||0))}%"></span></div>`:'<span class="r6-meta">未建立</span>'}</td><td><div class="r6-inline-actions">${r6Btn('详情','source-detail',null,'ghost sm',`data-id="${E(x.id)}"`)}${r6Btn('','pause',x.status==='paused'?'play':'pause','icon ghost sm',`data-id="${E(x.id)}" aria-label="${x.status==='paused'?'继续':'暂停'} ${E(x.name)}"`)}</div></td></tr>`).join('')}</tbody></table>`:`<div class="r6-empty">${I('search','lg')}<strong>${R6.search||R6.sourceFilter!=='all'?'没有匹配的日志源':'尚未添加日志源'}</strong>${R6.search||R6.sourceFilter!=='all'?r6Btn('清除筛选','clear-search','clear','sm'):''}</div>`}</div>${R6.selected&&r6Source(R6.selected)?r6Detail(r6Source(R6.selected)):''}</div>`;}'''
    for name, replacement in [('r6Page',page),('r6Sources',sources)]:
        text,n=re.subn(r'^function '+name+r'\(\).*$',lambda _:replacement,text,flags=re.M)
        if n!=1: raise ValueError('Expected one '+name)
    # Remove instructional sidebars in the actual wizard, not just visually hide them.
    text=re.sub(r'<aside class="r6-form-side">.*?</aside>', '', text)
    # Remove static tutorial blocks from storage; retain row-level mount state.
    text=re.sub(r'<div style="padding:20px 18px;max-width:900px">.*?</details></div>', '', text)
    # Remove redundant explanatory text while retaining field labels, warnings and errors.
    for old in [
        '<p class="hint">资源上限与实时、历史任务分开设置；保存后立即生效，状态栏显示服务端回执。</p>',
        '<div class="r6-note">250 GB RAM 优先留给文件系统页缓存，不将整份 1 GB 日志展开为浏览器或 Python 对象。首次建索引与已索引阅读分开限流。</div>',
        '<div class="hint">生产版由管理员在服务端管理，不把密码写入浏览器缓存。</div>',
        '<p class="r6-mininote" style="margin:0 0 14px">一个日志源可以包含多个远程目录，每个目录指定独立存储位置、子目录和解析规则。</p>',
    ]:text=text.replace(old,'')
    text=text.replace('其余预算项（服务端只读）','其余预算 · 只读')
    text=text.replace('<p>启用日志源后，采集、归档、索引与权限事件会由 /api/v2/jobs 与实时通道写入这里；不会用占位记录填充。</p>','')
    text=text.replace('<details class="r6-sub"><summary>记录范围</summary>采集、断线重连、归档、索引和权限事件均保留来源与时间；来自 /api/v2/jobs 与 SSE 增量。</details>','')
    # Real cache catalogue: source count is not a cache/file count.
    cache = """function r6Cache(){const items=LB.state.cache?.items||[];return `<div class="r6-toolbar"><span class="collection-count">${items.length} 个文件</span><span class="spacer"></span>${items.length?r6Btn('重建规则结果','cache-rebuild','refresh','sm'):''}</div><div class="r6-pane"><div class="r6-table-scroll">${items.length?`<table class="r6-table"><thead><tr><th>文件 / 代次</th><th>归档原文</th><th>结构索引</th><th>规则结果</th><th>操作</th></tr></thead><tbody>${items.map(x=>`<tr><td><button class="r6-link" data-r6="read-source" data-id="${E('srv-'+x.fileId)}">${E(x.displayName||x.fileId)}</button><div class="r6-meta">${E(x.relPath||'')} · ${E(x.generation)}</div></td><td class="mono">${E(x.size)} B</td><td>${E(x.layers?.structure?.state||'未建立')}</td><td>${E(x.layers?.rules?.state||'未建立')}</td><td>${r6Btn('详情','cache-detail','info','ghost sm',`data-id="${E(x.fileId)}"`)}</td></tr>`).join('')}</tbody></table>`:`<div class="r6-empty">${I('database','lg')}<strong>暂无解析缓存</strong></div>`}</div></div>`;}"""
    text = re.sub(r'^function r6Cache\(\).*$', lambda _: cache, text, flags=re.M)
    detail = """function r6CacheDetail(id){const x=(LB.state.cache?.items||[]).find(x=>x.fileId===id);if(!x)return;R6.cacheSelected=id;dialog('解析缓存 · '+(x.displayName||id),`<dl class="r6-kv"><dt>文件标识</dt><dd>${E(id)}</dd><dt>代次</dt><dd>${E(x.generation)}</dd><dt>原文</dt><dd>${E(x.size)} B</dd><dt>结构索引</dt><dd>${E(x.layers?.structure?.state||'未建立')}</dd><dt>规则结果</dt><dd>${E(x.layers?.rules?.state||'未建立')}</dd></dl><p class="hint">重建保留归档原文，完成前继续使用旧结果。</p>`,r6Btn('关闭','modal-close')+r6Btn('重建规则结果','cache-rebuild','refresh','primary'));}"""
    text = re.sub(r'^function r6CacheDetail\(id\).*$', lambda _: detail, text, flags=re.M)
    text = text.replace("(state.cache.items && state.cache.items[0] && state.cache.items[0].fileId)", "((state.cache.items || []).find(function (x) { return x.fileId === R6.cacheSelected; }) || (state.cache.items || [])[0] || {}).fileId")
    keyboard = '''document.addEventListener('keydown',function(e){const tab=e.target.closest('.collection-head [role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=Array.from(document.querySelectorAll('.collection-head [role="tab"]')),i=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;const id=tabs[next].dataset.id;tabs[next].click();document.getElementById('collection-tab-'+id)?.focus();});'''
    if keyboard not in text:
        text = text.replace('LB.paintStatus();\nLB.boot();', keyboard+'\nLB.paintStatus();\nLB.boot();')
    return text


def css():
    return Path(__file__).with_name('r6_collection_design.css').read_text()
